(()=>{const data=window.HANZI_SITE_MESSAGES;const overrides={...data.hi};Object.assign(data.hi,{"Skip to content":"मुख्य सामग्री पर जाएँ","Previous screenshot":"पिछला स्क्रीनशॉट","Next screenshot":"अगला स्क्रीनशॉट","raccoon.app.labs@gmail.com":"raccoon.app.labs@gmail.com","Hanzi Bloom":"Hanzi Bloom","Оферта":"सार्वजनिक प्रस्ताव","© 2026 Raccoon App Labs":"© 2026 Raccoon App Labs","Тарифы Plus":"Plus प्लान","Архивная редакция от 8 октября 2026 года.":"8 अक्टूबर 2026 का संग्रहित संस्करण।","Открыть действующую редакцию":"वर्तमान संस्करण खोलें","Какие данные использует Hanzi Bloom: прогресс, аккаунт, оплата, аналитика и реклама. Как запросить удаление аккаунта.":"Hanzi Bloom किन डेटा का उपयोग करता है: प्रगति, खाता, भुगतान, विश्लेषण और विज्ञापन। खाता मिटाने का अनुरोध कैसे करें।","Конфиденциальность · Hanzi Bloom":"गोपनीयता · Hanzi Bloom","Аккаунт и доступ":"खाता और पहुँच","Твои данные · понятные правила":"आपका डेटा · साफ़ नियम","Политика конфиденциальности":"गोपनीयता नीति","Политика обработки персональных данных. Редакция от 8 октября 2026 года.":"व्यक्तिगत डेटा प्रसंस्करण नीति। 8 अक्टूबर 2026 का संस्करण।","Почта — для входа. Заказ — для Plus.":"प्रवेश के लिए ईमेल। Plus के लिए ऑर्डर।","Учебный прогресс хранится на устройстве.":"अध्ययन प्रगति उपकरण पर रहती है।","Для аккаунта нужна почта; данные карты вводятся на стороне платёжного сервиса.":"खाते के लिए ईमेल चाहिए; कार्ड विवरण भुगतान सेवा में दिए जाते हैं।","Запросить удаление аккаунта можно по почте поддержки.":"सहायता के ईमेल पर खाता मिटाने का अनुरोध करें।","Содержание":"विषय-सूची","Кто обрабатывает":"डेटा कौन संसाधित करता है","Какие данные":"कौन-सा डेटा","Внешние сервисы":"बाहरी सेवाएँ","Сроки":"अवधियाँ","Удаление и права":"हटाना और अधिकार","1. Кто отвечает за данные":"1. डेटा का उत्तरदायी कौन है","Оператор: Покаместова Анастасия Максимовна, самозанятая (НПД), ИНН 695205887530, город Тверь.":"नियंत्रक: Anastasia Maksimovna Pokamestova, स्व-नियोजित (पेशेवर आय कर), कर पहचान संख्या 695205887530, Tver।","Raccoon App Labs — название разработчика.":"Raccoon App Labs डेवलपर का नाम है।","Контакт по вопросам данных:":"डेटा संबंधी संपर्क:",", телефон":", फ़ोन","Политика относится к Android-приложению Hanzi Bloom, его аккаунту, функциям Plus и страницам приложения на raccoon-app-labs.github.io.":"नीति Android के Hanzi Bloom, उसके खाते, Plus सुविधाओं और raccoon-app-labs.github.io के ऐप पेज पर लागू है।","Она не заменяет правила самостоятельных платёжных, почтовых и системных сервисов.":"यह स्वतंत्र भुगतान, ईमेल और सिस्टम सेवाओं के नियमों का विकल्प नहीं।","2. Какие данные и для чего":"2. कौन-सा डेटा और क्यों","Прогресс обучения":"अध्ययन प्रगति","Изучаемые слова, результаты упражнений, настройки и локально добавленные материалы сохраняются на устройстве.":"पढ़े शब्द, अभ्यास परिणाम, सेटिंग और स्थानीय सामग्री उपकरण पर सहेजी जाती है।","Вход в аккаунт Plus не переносит их на сервер и не включает синхронизацию.":"Plus खाते में प्रवेश इन्हें सर्वर पर नहीं भेजता और सिंक शामिल नहीं करता।","Экспорт выполняется в выбранный тобой файл.":"निर्यात आपके चुने फ़ाइल में होता है।","Системная резервная копия Android зависит от настроек устройства.":"Android बैकअप उपकरण की सेटिंग पर निर्भर है।","Аккаунт и вход":"खाता और प्रवेश","Адрес электронной почты, случайный идентификатор аккаунта, подтверждение почты, даты запросов и проверки кода.":"ईमेल, यादृच्छिक खाता पहचान, ईमेल सत्यापन और कोड अनुरोध तथा जाँच की तारीखें।","На сервере хранятся хеши одноразовых кодов и токенов сессий.":"सर्वर एकबारगी कोड और सत्र टोकन के हैश रखता है।","Они нужны для входа, проверки владельца заказа и восстановления оплаченного доступа.":"इनसे प्रवेश, ऑर्डर स्वामी की जाँच और सशुल्क पहुँच की बहाली होती है।","Покупка и Plus":"खरीद और Plus","Почта аккаунта, номер и статус заказа, идентификаторы продукта и предложения, сумма и валюта, выбранный срок, даты создания и подтверждения платежа, версия принятой оферты, дата окончания доступа, сведения о возврате или споре.":"खाते का ईमेल, ऑर्डर संख्या और स्थिति, उत्पाद तथा प्रस्ताव पहचान, राशि, मुद्रा, अवधि, भुगतान बनाने और पुष्टि की तारीखें, स्वीकृत संस्करण, पहुँच समाप्ति और वापसी या विवाद विवरण।","Ссылка на оплату хранится для продолжения созданного заказа.":"बनाया ऑर्डर जारी रखने के लिए भुगतान लिंक रखा जाता है।","Полный номер карты, CVC и банковские коды сервер Hanzi Bloom не получает.":"Hanzi Bloom सर्वर को पूरा कार्ड नंबर, CVC या बैंक कोड नहीं मिलते।","Безопасность и работа сайта":"सुरक्षा और वेबसाइट संचालन","IP-адрес и технические параметры соединения доступны инфраструктуре при обращении к ней.":"कनेक्ट करते समय अवसंरचना को IP और तकनीकी कनेक्शन विवरण उपलब्ध होते हैं।","Для ограничения запросов входа сервер приложения использует хеш IP-адреса и счётчики запросов.":"प्रवेश अनुरोध सीमित करने के लिए सर्वर IP हैश और अनुरोध गणक उपयोग करता है।","Это помогает предотвратить подбор кодов и массовые запросы.":"इससे कोड का अनुमान लगाने और सामूहिक अनुरोध रोकने में मदद मिलती है।","Обращение в поддержку":"सहायता अनुरोध","Твоя почта и содержание присланного обращения, включая добровольно приложенные файлы и сведения о заказе.":"आपका ईमेल और भेजा संदेश, स्वेच्छा से जुड़ी फ़ाइलों तथा ऑर्डर विवरण सहित।","Используем их, чтобы ответить, восстановить доступ или обработать возврат.":"इनका उपयोग उत्तर, पहुँच बहाली या धनवापसी के लिए होता है।","Не присылай реквизиты карты, банковские коды и пароль от почты.":"कार्ड विवरण, बैंक कोड या ईमेल पासवर्ड न भेजें।","Аналитика приложения":"ऐप विश्लेषण","MyTracker получает события запуска, сессий, переходов между экранами и выполнения упражнений, а также технические сведения SDK: версию приложения и системы, параметры устройства, сетевые и доступные устройству идентификаторы.":"MyTracker शुरुआत, सत्र, स्क्रीन बदलाव और अभ्यास घटनाएँ तथा SDK का तकनीकी डेटा पाता है: ऐप और सिस्टम संस्करण, उपकरण मापदंड, नेटवर्क और उपलब्ध उपकरण पहचान।","В пользовательские события Hanzi Bloom не добавляются текст поиска, свои слова, переводы, тексты историй, рукописные штрихи, почта аккаунта или токен входа.":"Hanzi Bloom की निजी घटनाओं में खोज पाठ, अपने शब्द, अनुवाद, कहानियाँ, हस्तलिखित स्ट्रोक, खाते का ईमेल या प्रवेश टोकन नहीं जुड़ते।","Реклама":"विज्ञापन","Yandex Mobile Ads использует технические данные устройства, соединения, рекламные идентификаторы и сведения о показах для работы рекламы и защиты от недействительного трафика.":"Yandex Mobile Ads विज्ञापन दिखाने और अमान्य ट्रैफ़िक रोकने के लिए उपकरण, कनेक्शन, विज्ञापन पहचान और दृश्य संबंधी तकनीकी डेटा उपयोग करता है।","Передача геолокации для рекламы отключена настройкой приложения.":"ऐप सेटिंग में विज्ञापन हेतु स्थान भेजना बंद है।","Персонализация управляется переключателем в настройках Hanzi Bloom; при выключенной персонализации техническая обработка для показа рекламы может сохраняться.":"Hanzi Bloom की सेटिंग से वैयक्तिकरण नियंत्रित होता है; बंद करने पर भी विज्ञापन दिखाने का तकनीकी प्रसंस्करण रह सकता है।","Голосовая и рукописная практика":"बोलने और लिखने का अभ्यास","Микрофон включается для выбранного тобой голосового упражнения после разрешения Android.":"चुने मौखिक अभ्यास के लिए Android अनुमति के बाद माइक्रोफ़ोन चालू होता है।","Системная служба распознавания речи может обрабатывать звук на своих серверах в зависимости от устройства и выбранного сервиса.":"सिस्टम की वाणी पहचान सेवा उपकरण और चुनी सेवा के अनुसार अपने सर्वर पर आवाज़ संसाधित कर सकती है।","Сервер аккаунта Hanzi Bloom аудиозаписи не получает.":"Hanzi Bloom खाता सर्वर को ऑडियो रिकॉर्डिंग नहीं मिलती।","Распознавание рукописных штрихов выполняется на устройстве; модели могут загружаться через сервис их поставщика.":"हस्तलिखित स्ट्रोक की पहचान उपकरण पर होती है; मॉडल आपूर्तिकर्ता की सेवा से डाउनलोड हो सकते हैं।","Категории пользователей: посетители сайта, пользователи приложения и аккаунта, покупатели Plus и обратившиеся в поддержку.":"उपयोगकर्ता वर्ग: वेबसाइट आगंतुक, ऐप और खाता उपयोगकर्ता, Plus खरीदार और सहायता से संपर्क करने वाले।","Специальные категории данных и биометрическая идентификация для аккаунта и покупки не используются.":"खाता या खरीद के लिए विशेष डेटा वर्ग और बायोमेट्रिक पहचान का उपयोग नहीं होता।","3. Основания и способы обработки":"3. प्रसंस्करण के आधार और तरीके","Почта, данные аккаунта и заказа нужны для действий по запросу пользователя и исполнения договора.":"ईमेल, खाता और ऑर्डर डेटा उपयोगकर्ता के अनुरोध और अनुबंध पूरा करने के लिए आवश्यक हैं।","Данные расчётов сохраняются также для обязательных требований закона.":"भुगतान रिकॉर्ड अनिवार्य कानूनी जरूरतों के लिए भी रखे जाते हैं।","Технические данные используются для безопасности и улучшения приложения при наличии применимого правового основания.":"उचित कानूनी आधार होने पर तकनीकी डेटा सुरक्षा और सुधार के लिए उपयोग होता है।","Когда необходимо согласие, оно должно оформляться отдельно; эта политика не является согласием на рассылку или на неограниченную передачу данных.":"आवश्यक सहमति अलग ली जाती है; यह नीति विज्ञापन या असीमित डेटा हस्तांतरण की सहमति नहीं।","Обработка автоматизированная, а при обращениях — также с участием оператора: сбор, хранение, проверка, использование, предоставление необходимым сервисам, исправление и удаление.":"प्रसंस्करण स्वचालित और अनुरोधों में मानव द्वारा भी होता है: संग्रह, भंडारण, जाँच, उपयोग, आवश्यक सेवाओं को देना, सुधार और हटाना।","Персональные данные аккаунта не публикуются и не продаются.":"व्यक्तिगत खाता डेटा प्रकाशित या बेचा नहीं जाता।","Почта входа используется для кодов и сообщений по услуге, а не для рекламной рассылки.":"प्रवेश ईमेल कोड और सेवा संदेशों के लिए है, विज्ञापन के लिए नहीं।","4. Где обрабатываются данные":"4. डेटा कहाँ संसाधित होता है","Yandex Cloud.":"Yandex Cloud।","Сервер аккаунта и база данных размещаются в российском регионе ru-central1. Здесь проверяются коды, сессии, заказы и доступ Plus.":"खाता सर्वर और डेटाबेस रूसी ru-central1 क्षेत्र में हैं। यहीं कोड, सत्र, ऑर्डर और Plus पहुँच जाँचे जाते हैं।","Документы Yandex Cloud":"Yandex Cloud दस्तावेज़","Google / Gmail.":"Google / Gmail।","Почта и код входа передаются почтовому сервису для доставки письма. Обращения поддержки обрабатываются в Gmail.":"ईमेल पहुँचाने के लिए पता और कोड मेल सेवा को दिए जाते हैं। सहायता अनुरोध Gmail में देखे जाते हैं।","Политика Google":"Google नीति","Lava / LAVALANE LTD (Кипр).":"Lava / LAVALANE LTD (साइप्रस)।","Для международного заказа передаются почта, предложение, валюта и параметры покупки.":"अंतरराष्ट्रीय ऑर्डर में ईमेल, प्रस्ताव, मुद्रा और खरीद मापदंड भेजे जाते हैं।","Платёжные сведения покупатель вводит у Lava или её платёжных партнёров; Hanzi Bloom получает подтверждение заказа и возврата.":"खरीदार Lava या उसके भुगतान साझेदारों को विवरण देता है; Hanzi Bloom को ऑर्डर और धनवापसी की पुष्टि मिलती है।","Политика Lava":"Lava नीति","Robokassa.":"Robokassa।","При выборе доступного российского способа оплаты данные заказа обрабатываются этим сервисом.":"उपलब्ध रूसी भुगतान विकल्प चुनने पर यह सेवा ऑर्डर डेटा संसाधित करती है।","Пока российский приём оплаты не открыт, покупка через него недоступна.":"रूसी भुगतान शुरू होने तक उससे खरीद उपलब्ध नहीं।","Политика Robokassa":"Robokassa नीति","GitHub Pages.":"GitHub Pages।","Размещает публичные страницы сайта и получает технические данные посещений. База аккаунтов и заказов не размещается в репозитории.":"सार्वजनिक पेज होस्ट करता और तकनीकी विज़िट डेटा पाता है। खाता और ऑर्डर डेटाबेस रिपॉज़िटरी में नहीं है।","Политика GitHub":"GitHub नीति","MyTracker (VK) и Yandex Mobile Ads.":"MyTracker (VK) और Yandex Mobile Ads।","Получают данные аналитики и рекламы, описанные выше, в версиях приложения с этими SDK.":"इन SDK वाले संस्करणों में ऊपर वर्णित विश्लेषण और विज्ञापन डेटा मिलता है।","Политика MyTracker":"MyTracker नीति","политика Яндекса":"Yandex नीति","Google, GitHub, Lava и системная служба распознавания могут обрабатывать сведения за пределами России; Lava указывает Кипр как место нахождения своей компании.":"Google, GitHub, Lava और सिस्टम वाणी पहचान रूस के बाहर डेटा संसाधित कर सकते हैं; Lava अपनी कंपनी का स्थान साइप्रस बताता है।","Российское размещение базы аккаунтов не означает, что все перечисленные сервисы работают только в России.":"रूस में खाता डेटाबेस होने का अर्थ सभी सेवाओं का केवल रूस में चलना नहीं।","Международная передача требует самостоятельного применимого основания и соблюдения установленных законом процедур; публикация политики их не заменяет.":"अंतरराष्ट्रीय हस्तांतरण के लिए अलग कानूनी आधार और प्रक्रियाएँ चाहिए; नीति प्रकाशित करना उनका विकल्प नहीं।","5. Хранение в браузере и на устройстве":"5. ब्राउज़र और उपकरण भंडारण","Страница покупки использует sessionStorage для токена текущего входа, почты и идентификатора начатого заказа.":"खरीद पेज वर्तमान टोकन, ईमेल और शुरू ऑर्डर की पहचान के लिए sessionStorage उपयोग करता है।","Это позволяет вернуться после оплаты и восстановить ответ, не создавая новый счёт.":"इससे भुगतान के बाद लौटकर नया बिल बनाए बिना उत्तर बहाल हो सकता है।","Кнопка «Выйти» очищает эти сведения и отправляет запрос завершения сессии.":"«साइन आउट» यह जानकारी मिटाकर सत्र बंद करने का अनुरोध भेजता है।","Браузер может восстановить сеанс при восстановлении вкладок; данные также можно удалить в настройках сайта.":"टैब बहाल करते समय ब्राउज़र सत्र लौटा सकता है; वेबसाइट सेटिंग में डेटा हटा सकते हैं।","На странице покупки не установлены рекламные или аналитические счётчики.":"खरीद पेज पर विज्ञापन या विश्लेषण ट्रैकर नहीं हैं।","Инфраструктура GitHub и страницы внешних платёжных сервисов имеют собственные правила технического хранения и cookie.":"GitHub अवसंरचना और बाहरी भुगतान पेज के अपने भंडारण और कुकी नियम हैं।","В приложении токен аккаунта хранится с шифрованием через Android Keystore и исключён из системной резервной копии.":"ऐप का खाता टोकन Android Keystore से एन्क्रिप्ट है और सिस्टम बैकअप में नहीं जाता।","Удаление данных приложения удаляет локальный прогресс и настройки, но само по себе не удаляет серверный аккаунт или сведения о покупке.":"ऐप डेटा हटाने से स्थानीय प्रगति और सेटिंग मिटती हैं, सर्वर खाता या खरीद अपने-आप नहीं।","6. Сроки и защита":"6. अवधि और सुरक्षा","Код входа действует 10 минут; сессия — до 30 дней и прекращается раньше после подтверждённого выхода.":"प्रवेश कोड 10 मिनट; सत्र अधिकतम 30 दिन रहता है और पुष्ट साइन आउट पर पहले समाप्त होता है।","Неподтверждённый аккаунт хранится до 24 часов.":"असत्यापित खाता अधिकतम 24 घंटे रखा जाता है।","Временные счётчики защиты имеют срок от минуты до суток, в том числе до часа для ограничения запросов с одного IP-адреса.":"अस्थायी सुरक्षा गणक एक मिनट से एक दिन, और एक IP के अनुरोध सीमित करने हेतु अधिकतम एक घंटे रहते हैं।","Истечение срока исключает их использование; физическое удаление временных записей выполняется механизмом базы данных и может происходить позднее.":"समाप्ति पर उपयोग रुकता है; डेटाबेस अस्थायी रिकॉर्ड बाद में भौतिक रूप से हटा सकता है।","Подтверждённый аккаунт и история заказов автоматически не удаляются при окончании Plus.":"Plus समाप्त होने पर सत्यापित खाता और ऑर्डर इतिहास अपने-आप नहीं मिटते।","Аккаунт хранится для восстановления доступа, пока он нужен пользователю; удаление запрашивается по правилам следующего раздела.":"पहुँच बहाल करने के लिए जरूरत तक खाता रहता है; हटाने के नियम अगले अनुभाग में हैं।","Данные платежей и обращений сохраняются только на срок, необходимый для исполнения обязательств, возвратов, разрешения споров и обязательного учёта, затем удаляются или обезличиваются.":"भुगतान और अनुरोध डेटा अनुबंध, वापसी, विवाद और अनिवार्य लेखांकन के लिए जरूरी अवधि तक रहता है, फिर मिटता या अनाम किया जाता है।","Обязательные записи могут сохраняться после удаления аккаунта.":"अनिवार्य रिकॉर्ड खाता मिटने के बाद भी रह सकते हैं।","Соединение с сервером защищено HTTPS.":"सर्वर कनेक्शन HTTPS से सुरक्षित है।","Применяются ограничение запросов, проверка принадлежности заказа, контроль доступа к инфраструктуре и хранение хешей вместо открытых кодов и серверных токенов.":"अनुरोध सीमाएँ, ऑर्डर स्वामी सत्यापन, अवसंरचना पहुँच नियंत्रण और खुले कोड तथा टोकन के बजाय हैश उपयोग होते हैं।","Не передавай другим людям код входа.":"अपना प्रवेश कोड किसी को न दें।","Оплата и активация не подтверждаются одним только адресом страницы «успех»: сервер проверяет уведомление и сведения платёжного сервиса.":"केवल «सफलता» पेज का पता भुगतान या सक्रियण का प्रमाण नहीं; सर्वर सेवा की सूचना और विवरण जाँचता है।","7. Уточнение и удаление данных":"7. डेटा सुधारना और हटाना","Хочешь удалить аккаунт?":"खाता मिटाना चाहते हैं?","Напиши с почты аккаунта на":"खाते वाले ईमेल से लिखें",", тема: «Удаление аккаунта Hanzi Bloom». Укажи, что нужно удалить серверный аккаунт.":", विषय: «Hanzi Bloom खाता हटाएँ»। बताएँ कि सर्वर खाता मिटाना है।","Можно запросить сведения об обработке своих данных, исправление, блокирование или удаление, а также отозвать согласие, если обработка основана на нём.":"अपने डेटा की जानकारी, सुधार, रोक या हटाने का अनुरोध और सहमति आधारित प्रसंस्करण की सहमति वापस ले सकते हैं।","Для защиты аккаунта оператор проверяет, что обращается его владелец.":"खाते की रक्षा हेतु नियंत्रक स्वामी की पहचान जाँचता है।","Карта, CVC и код входа для обращения не нужны.":"अनुरोध के लिए कार्ड, CVC या प्रवेश कोड नहीं चाहिए।","Если сохранить часть записей требует закон, сообщаем об этом при ответе.":"कानून कुछ रिकॉर्ड रखना माँगे तो उत्तर में बताया जाता है।","Обращения рассматриваются в применимые законные сроки.":"अनुरोध लागू कानूनी समयसीमा में देखे जाते हैं।","Удаление аккаунта прекращает возможность входа и восстановления Plus через него; перед удалением действующей покупки можно отдельно обсудить отказ от услуги и возврат по":"खाता मिटने से उसमें प्रवेश और Plus बहाली समाप्त होती है; सक्रिय खरीद मिटाने से पहले सेवा छोड़ने और वापसी पर अलग चर्चा हो सकती है, इसके अनुसार:","оферте":"प्रस्ताव","Удаление локального прогресса выполняется через настройки Android или приложения.":"स्थानीय प्रगति Android या ऐप सेटिंग से हटती है।","Запросы к самостоятельным внешним сервисам можно направлять им по указанным выше политикам.":"स्वतंत्र बाहरी सेवाओं को ऊपर जुड़ी उनकी नीतियों के अनुसार अनुरोध भेज सकते हैं।","По вопросам защиты персональных данных можно обратиться к оператору, а также в уполномоченный орган — Роскомнадзор — или в суд.":"डेटा सुरक्षा के लिए नियंत्रक, अधिकृत प्राधिकरण Roskomnadzor या अदालत से संपर्क कर सकते हैं।","8. Дети и изменения политики":"8. बच्चे और नीति बदलाव","Аккаунт для покупки используется дееспособным покупателем; при необходимости покупку совершает законный представитель.":"खरीद खाता कानूनी रूप से सक्षम खरीदार उपयोग करता है; आवश्यकता पर कानूनी प्रतिनिधि खरीदता है।","В обращении о данных ребёнка представитель может связаться с оператором.":"प्रतिनिधि बच्चे के डेटा पर नियंत्रक से संपर्क कर सकता है।","Приложение не запрашивает дату рождения для покупки.":"खरीद के लिए जन्मतिथि नहीं माँगी जाती।","Новая редакция публикуется по этому адресу с датой изменения.":"नया संस्करण बदलाव की तारीख सहित इसी पते पर प्रकाशित होता है।","Если меняются цели или состав обработки, для которых необходимо отдельное согласие, обновление текста само по себе его не заменяет.":"अलग सहमति जरूरी होने वाले उद्देश्य या डेटा वर्ग बदलें तो पाठ अपडेट करना सहमति का विकल्प नहीं।","Предыдущие редакции доступны по запросу в поддержку.":"पुराने संस्करण सहायता से माँग सकते हैं।","Поддержка":"सहायता","Explore app":"ऐप देखें","Translation for convenience. Original document: {language}.":"सुविधा के लिए अनुवाद। मूल दस्तावेज़ की भाषा: {language}।","Show original document":"मूल दस्तावेज़ दिखाएँ","Language":"भाषा","Choose your language":"अपनी भाषा चुनें","Search languages":"भाषाएँ खोजें","Close language selection":"भाषा सूची बंद करें","Language changed to {language}":"भाषा {language} कर दी गई","The page language does not change your payment region or currency.":"पेज की भाषा भुगतान क्षेत्र या मुद्रा नहीं बदलती।","No languages found":"कोई भाषा नहीं मिली","Use device language":"उपकरण की भाषा उपयोग करें","PERFECT KICK":"शानदार छलाँग!","{v0} · {v1}":"{v0} · {v1}","{v0} — {v1}. Found!":"{v0} — {v1}. मिल गया!","{v0} — {v1}. Ключ найден!":"{v0} — {v1}. मिल गया!","{v0} · {v1} servings":"{v0} · {v1} सर्विंग","{v0} · {v1} порц.":"{v0} · {v1} सर्विंग","{v0} — {v1} pcs":"{v0} — {v1} नग","{v0} — {v1} шт.":"{v0} — {v1} नग","{v0} — {v1} g":"{v0} — {v1} g","{v0} — {v1} г":"{v0} — {v1} g","Новый код · {seconds} с":"नया कोड · {seconds} सेकंड","· {v0} servings":"· {v0} सर्विंग","· {v0} порц.":"· {v0} सर्विंग","{remaining} left · {done} done":"{remaining} बाकी · {done} पूरे","Finish · {count} bought":"समाप्त करें · {count} खरीदे","{remaining} осталось · {done} готово":"{remaining} बाकी · {done} पूरे","Куплено: {count} · завершить":"समाप्त करें · {count} खरीदे"},overrides);Object.assign(window.HANZI_SOURCE_ALIASES||{},{"मुख्य सामग्री पर जाएँ":"Skip to content","पिछला स्क्रीनशॉट":"Previous screenshot","अगला स्क्रीनशॉट":"Next screenshot","सार्वजनिक प्रस्ताव":"Оферта","Plus प्लान":"Тарифы Plus","8 अक्टूबर 2026 का संग्रहित संस्करण।":"Архивная редакция от 8 октября 2026 года.","वर्तमान संस्करण खोलें":"Открыть действующую редакцию","Hanzi Bloom किन डेटा का उपयोग करता है: प्रगति, खाता, भुगतान, विश्लेषण और विज्ञापन। खाता मिटाने का अनुरोध कैसे करें।":"Какие данные использует Hanzi Bloom: прогресс, аккаунт, оплата, аналитика и реклама. Как запросить удаление аккаунта.","गोपनीयता · Hanzi Bloom":"Конфиденциальность · Hanzi Bloom","खाता और पहुँच":"Аккаунт и доступ","आपका डेटा · साफ़ नियम":"Твои данные · понятные правила","गोपनीयता नीति":"Политика конфиденциальности","व्यक्तिगत डेटा प्रसंस्करण नीति। 8 अक्टूबर 2026 का संस्करण।":"Политика обработки персональных данных. Редакция от 8 октября 2026 года.","प्रवेश के लिए ईमेल। Plus के लिए ऑर्डर।":"Почта — для входа. Заказ — для Plus.","अध्ययन प्रगति उपकरण पर रहती है।":"Учебный прогресс хранится на устройстве.","खाते के लिए ईमेल चाहिए; कार्ड विवरण भुगतान सेवा में दिए जाते हैं।":"Для аккаунта нужна почта; данные карты вводятся на стороне платёжного сервиса.","सहायता के ईमेल पर खाता मिटाने का अनुरोध करें।":"Запросить удаление аккаунта можно по почте поддержки.","विषय-सूची":"Содержание","डेटा कौन संसाधित करता है":"Кто обрабатывает","कौन-सा डेटा":"Какие данные","बाहरी सेवाएँ":"Внешние сервисы","अवधियाँ":"Сроки","हटाना और अधिकार":"Удаление и права","1. डेटा का उत्तरदायी कौन है":"1. Кто отвечает за данные","नियंत्रक: Anastasia Maksimovna Pokamestova, स्व-नियोजित (पेशेवर आय कर), कर पहचान संख्या 695205887530, Tver।":"Оператор: Покаместова Анастасия Максимовна, самозанятая (НПД), ИНН 695205887530, город Тверь.","Raccoon App Labs डेवलपर का नाम है।":"Raccoon App Labs — название разработчика.","डेटा संबंधी संपर्क:":"Контакт по вопросам данных:",", फ़ोन":", телефон","नीति Android के Hanzi Bloom, उसके खाते, Plus सुविधाओं और raccoon-app-labs.github.io के ऐप पेज पर लागू है।":"Политика относится к Android-приложению Hanzi Bloom, его аккаунту, функциям Plus и страницам приложения на raccoon-app-labs.github.io.","यह स्वतंत्र भुगतान, ईमेल और सिस्टम सेवाओं के नियमों का विकल्प नहीं।":"Она не заменяет правила самостоятельных платёжных, почтовых и системных сервисов.","2. कौन-सा डेटा और क्यों":"2. Какие данные и для чего","अध्ययन प्रगति":"Прогресс обучения","पढ़े शब्द, अभ्यास परिणाम, सेटिंग और स्थानीय सामग्री उपकरण पर सहेजी जाती है।":"Изучаемые слова, результаты упражнений, настройки и локально добавленные материалы сохраняются на устройстве.","Plus खाते में प्रवेश इन्हें सर्वर पर नहीं भेजता और सिंक शामिल नहीं करता।":"Вход в аккаунт Plus не переносит их на сервер и не включает синхронизацию.","निर्यात आपके चुने फ़ाइल में होता है।":"Экспорт выполняется в выбранный тобой файл.","Android बैकअप उपकरण की सेटिंग पर निर्भर है।":"Системная резервная копия Android зависит от настроек устройства.","खाता और प्रवेश":"Аккаунт и вход","ईमेल, यादृच्छिक खाता पहचान, ईमेल सत्यापन और कोड अनुरोध तथा जाँच की तारीखें।":"Адрес электронной почты, случайный идентификатор аккаунта, подтверждение почты, даты запросов и проверки кода.","सर्वर एकबारगी कोड और सत्र टोकन के हैश रखता है।":"На сервере хранятся хеши одноразовых кодов и токенов сессий.","इनसे प्रवेश, ऑर्डर स्वामी की जाँच और सशुल्क पहुँच की बहाली होती है।":"Они нужны для входа, проверки владельца заказа и восстановления оплаченного доступа.","खरीद और Plus":"Покупка и Plus","खाते का ईमेल, ऑर्डर संख्या और स्थिति, उत्पाद तथा प्रस्ताव पहचान, राशि, मुद्रा, अवधि, भुगतान बनाने और पुष्टि की तारीखें, स्वीकृत संस्करण, पहुँच समाप्ति और वापसी या विवाद विवरण।":"Почта аккаунта, номер и статус заказа, идентификаторы продукта и предложения, сумма и валюта, выбранный срок, даты создания и подтверждения платежа, версия принятой оферты, дата окончания доступа, сведения о возврате или споре.","बनाया ऑर्डर जारी रखने के लिए भुगतान लिंक रखा जाता है।":"Ссылка на оплату хранится для продолжения созданного заказа.","Hanzi Bloom सर्वर को पूरा कार्ड नंबर, CVC या बैंक कोड नहीं मिलते।":"Полный номер карты, CVC и банковские коды сервер Hanzi Bloom не получает.","सुरक्षा और वेबसाइट संचालन":"Безопасность и работа сайта","कनेक्ट करते समय अवसंरचना को IP और तकनीकी कनेक्शन विवरण उपलब्ध होते हैं।":"IP-адрес и технические параметры соединения доступны инфраструктуре при обращении к ней.","प्रवेश अनुरोध सीमित करने के लिए सर्वर IP हैश और अनुरोध गणक उपयोग करता है।":"Для ограничения запросов входа сервер приложения использует хеш IP-адреса и счётчики запросов.","इससे कोड का अनुमान लगाने और सामूहिक अनुरोध रोकने में मदद मिलती है।":"Это помогает предотвратить подбор кодов и массовые запросы.","सहायता अनुरोध":"Обращение в поддержку","आपका ईमेल और भेजा संदेश, स्वेच्छा से जुड़ी फ़ाइलों तथा ऑर्डर विवरण सहित।":"Твоя почта и содержание присланного обращения, включая добровольно приложенные файлы и сведения о заказе.","इनका उपयोग उत्तर, पहुँच बहाली या धनवापसी के लिए होता है।":"Используем их, чтобы ответить, восстановить доступ или обработать возврат.","कार्ड विवरण, बैंक कोड या ईमेल पासवर्ड न भेजें।":"Не присылай реквизиты карты, банковские коды и пароль от почты.","ऐप विश्लेषण":"Аналитика приложения","MyTracker शुरुआत, सत्र, स्क्रीन बदलाव और अभ्यास घटनाएँ तथा SDK का तकनीकी डेटा पाता है: ऐप और सिस्टम संस्करण, उपकरण मापदंड, नेटवर्क और उपलब्ध उपकरण पहचान।":"MyTracker получает события запуска, сессий, переходов между экранами и выполнения упражнений, а также технические сведения SDK: версию приложения и системы, параметры устройства, сетевые и доступные устройству идентификаторы.","Hanzi Bloom की निजी घटनाओं में खोज पाठ, अपने शब्द, अनुवाद, कहानियाँ, हस्तलिखित स्ट्रोक, खाते का ईमेल या प्रवेश टोकन नहीं जुड़ते।":"В пользовательские события Hanzi Bloom не добавляются текст поиска, свои слова, переводы, тексты историй, рукописные штрихи, почта аккаунта или токен входа.","विज्ञापन":"Реклама","Yandex Mobile Ads विज्ञापन दिखाने और अमान्य ट्रैफ़िक रोकने के लिए उपकरण, कनेक्शन, विज्ञापन पहचान और दृश्य संबंधी तकनीकी डेटा उपयोग करता है।":"Yandex Mobile Ads использует технические данные устройства, соединения, рекламные идентификаторы и сведения о показах для работы рекламы и защиты от недействительного трафика.","ऐप सेटिंग में विज्ञापन हेतु स्थान भेजना बंद है।":"Передача геолокации для рекламы отключена настройкой приложения.","Hanzi Bloom की सेटिंग से वैयक्तिकरण नियंत्रित होता है; बंद करने पर भी विज्ञापन दिखाने का तकनीकी प्रसंस्करण रह सकता है।":"Персонализация управляется переключателем в настройках Hanzi Bloom; при выключенной персонализации техническая обработка для показа рекламы может сохраняться.","बोलने और लिखने का अभ्यास":"Голосовая и рукописная практика","चुने मौखिक अभ्यास के लिए Android अनुमति के बाद माइक्रोफ़ोन चालू होता है।":"Микрофон включается для выбранного тобой голосового упражнения после разрешения Android.","सिस्टम की वाणी पहचान सेवा उपकरण और चुनी सेवा के अनुसार अपने सर्वर पर आवाज़ संसाधित कर सकती है।":"Системная служба распознавания речи может обрабатывать звук на своих серверах в зависимости от устройства и выбранного сервиса.","Hanzi Bloom खाता सर्वर को ऑडियो रिकॉर्डिंग नहीं मिलती।":"Сервер аккаунта Hanzi Bloom аудиозаписи не получает.","हस्तलिखित स्ट्रोक की पहचान उपकरण पर होती है; मॉडल आपूर्तिकर्ता की सेवा से डाउनलोड हो सकते हैं।":"Распознавание рукописных штрихов выполняется на устройстве; модели могут загружаться через сервис их поставщика.","उपयोगकर्ता वर्ग: वेबसाइट आगंतुक, ऐप और खाता उपयोगकर्ता, Plus खरीदार और सहायता से संपर्क करने वाले।":"Категории пользователей: посетители сайта, пользователи приложения и аккаунта, покупатели Plus и обратившиеся в поддержку.","खाता या खरीद के लिए विशेष डेटा वर्ग और बायोमेट्रिक पहचान का उपयोग नहीं होता।":"Специальные категории данных и биометрическая идентификация для аккаунта и покупки не используются.","3. प्रसंस्करण के आधार और तरीके":"3. Основания и способы обработки","ईमेल, खाता और ऑर्डर डेटा उपयोगकर्ता के अनुरोध और अनुबंध पूरा करने के लिए आवश्यक हैं।":"Почта, данные аккаунта и заказа нужны для действий по запросу пользователя и исполнения договора.","भुगतान रिकॉर्ड अनिवार्य कानूनी जरूरतों के लिए भी रखे जाते हैं।":"Данные расчётов сохраняются также для обязательных требований закона.","उचित कानूनी आधार होने पर तकनीकी डेटा सुरक्षा और सुधार के लिए उपयोग होता है।":"Технические данные используются для безопасности и улучшения приложения при наличии применимого правового основания.","आवश्यक सहमति अलग ली जाती है; यह नीति विज्ञापन या असीमित डेटा हस्तांतरण की सहमति नहीं।":"Когда необходимо согласие, оно должно оформляться отдельно; эта политика не является согласием на рассылку или на неограниченную передачу данных.","प्रसंस्करण स्वचालित और अनुरोधों में मानव द्वारा भी होता है: संग्रह, भंडारण, जाँच, उपयोग, आवश्यक सेवाओं को देना, सुधार और हटाना।":"Обработка автоматизированная, а при обращениях — также с участием оператора: сбор, хранение, проверка, использование, предоставление необходимым сервисам, исправление и удаление.","व्यक्तिगत खाता डेटा प्रकाशित या बेचा नहीं जाता।":"Персональные данные аккаунта не публикуются и не продаются.","प्रवेश ईमेल कोड और सेवा संदेशों के लिए है, विज्ञापन के लिए नहीं।":"Почта входа используется для кодов и сообщений по услуге, а не для рекламной рассылки.","4. डेटा कहाँ संसाधित होता है":"4. Где обрабатываются данные","Yandex Cloud।":"Yandex Cloud.","खाता सर्वर और डेटाबेस रूसी ru-central1 क्षेत्र में हैं। यहीं कोड, सत्र, ऑर्डर और Plus पहुँच जाँचे जाते हैं।":"Сервер аккаунта и база данных размещаются в российском регионе ru-central1. Здесь проверяются коды, сессии, заказы и доступ Plus.","Yandex Cloud दस्तावेज़":"Документы Yandex Cloud","Google / Gmail।":"Google / Gmail.","ईमेल पहुँचाने के लिए पता और कोड मेल सेवा को दिए जाते हैं। सहायता अनुरोध Gmail में देखे जाते हैं।":"Почта и код входа передаются почтовому сервису для доставки письма. Обращения поддержки обрабатываются в Gmail.","Google नीति":"Политика Google","Lava / LAVALANE LTD (साइप्रस)।":"Lava / LAVALANE LTD (Кипр).","अंतरराष्ट्रीय ऑर्डर में ईमेल, प्रस्ताव, मुद्रा और खरीद मापदंड भेजे जाते हैं।":"Для международного заказа передаются почта, предложение, валюта и параметры покупки.","खरीदार Lava या उसके भुगतान साझेदारों को विवरण देता है; Hanzi Bloom को ऑर्डर और धनवापसी की पुष्टि मिलती है।":"Платёжные сведения покупатель вводит у Lava или её платёжных партнёров; Hanzi Bloom получает подтверждение заказа и возврата.","Lava नीति":"Политика Lava","Robokassa।":"Robokassa.","उपलब्ध रूसी भुगतान विकल्प चुनने पर यह सेवा ऑर्डर डेटा संसाधित करती है।":"При выборе доступного российского способа оплаты данные заказа обрабатываются этим сервисом.","रूसी भुगतान शुरू होने तक उससे खरीद उपलब्ध नहीं।":"Пока российский приём оплаты не открыт, покупка через него недоступна.","Robokassa नीति":"Политика Robokassa","GitHub Pages।":"GitHub Pages.","सार्वजनिक पेज होस्ट करता और तकनीकी विज़िट डेटा पाता है। खाता और ऑर्डर डेटाबेस रिपॉज़िटरी में नहीं है।":"Размещает публичные страницы сайта и получает технические данные посещений. База аккаунтов и заказов не размещается в репозитории.","GitHub नीति":"Политика GitHub","MyTracker (VK) और Yandex Mobile Ads।":"MyTracker (VK) и Yandex Mobile Ads.","इन SDK वाले संस्करणों में ऊपर वर्णित विश्लेषण और विज्ञापन डेटा मिलता है।":"Получают данные аналитики и рекламы, описанные выше, в версиях приложения с этими SDK.","MyTracker नीति":"Политика MyTracker","Yandex नीति":"политика Яндекса","Google, GitHub, Lava और सिस्टम वाणी पहचान रूस के बाहर डेटा संसाधित कर सकते हैं; Lava अपनी कंपनी का स्थान साइप्रस बताता है।":"Google, GitHub, Lava и системная служба распознавания могут обрабатывать сведения за пределами России; Lava указывает Кипр как место нахождения своей компании.","रूस में खाता डेटाबेस होने का अर्थ सभी सेवाओं का केवल रूस में चलना नहीं।":"Российское размещение базы аккаунтов не означает, что все перечисленные сервисы работают только в России.","अंतरराष्ट्रीय हस्तांतरण के लिए अलग कानूनी आधार और प्रक्रियाएँ चाहिए; नीति प्रकाशित करना उनका विकल्प नहीं।":"Международная передача требует самостоятельного применимого основания и соблюдения установленных законом процедур; публикация политики их не заменяет.","5. ब्राउज़र और उपकरण भंडारण":"5. Хранение в браузере и на устройстве","खरीद पेज वर्तमान टोकन, ईमेल और शुरू ऑर्डर की पहचान के लिए sessionStorage उपयोग करता है।":"Страница покупки использует sessionStorage для токена текущего входа, почты и идентификатора начатого заказа.","इससे भुगतान के बाद लौटकर नया बिल बनाए बिना उत्तर बहाल हो सकता है।":"Это позволяет вернуться после оплаты и восстановить ответ, не создавая новый счёт.","«साइन आउट» यह जानकारी मिटाकर सत्र बंद करने का अनुरोध भेजता है।":"Кнопка «Выйти» очищает эти сведения и отправляет запрос завершения сессии.","टैब बहाल करते समय ब्राउज़र सत्र लौटा सकता है; वेबसाइट सेटिंग में डेटा हटा सकते हैं।":"Браузер может восстановить сеанс при восстановлении вкладок; данные также можно удалить в настройках сайта.","खरीद पेज पर विज्ञापन या विश्लेषण ट्रैकर नहीं हैं।":"На странице покупки не установлены рекламные или аналитические счётчики.","GitHub अवसंरचना और बाहरी भुगतान पेज के अपने भंडारण और कुकी नियम हैं।":"Инфраструктура GitHub и страницы внешних платёжных сервисов имеют собственные правила технического хранения и cookie.","ऐप का खाता टोकन Android Keystore से एन्क्रिप्ट है और सिस्टम बैकअप में नहीं जाता।":"В приложении токен аккаунта хранится с шифрованием через Android Keystore и исключён из системной резервной копии.","ऐप डेटा हटाने से स्थानीय प्रगति और सेटिंग मिटती हैं, सर्वर खाता या खरीद अपने-आप नहीं।":"Удаление данных приложения удаляет локальный прогресс и настройки, но само по себе не удаляет серверный аккаунт или сведения о покупке.","6. अवधि और सुरक्षा":"6. Сроки и защита","प्रवेश कोड 10 मिनट; सत्र अधिकतम 30 दिन रहता है और पुष्ट साइन आउट पर पहले समाप्त होता है।":"Код входа действует 10 минут; сессия — до 30 дней и прекращается раньше после подтверждённого выхода.","असत्यापित खाता अधिकतम 24 घंटे रखा जाता है।":"Неподтверждённый аккаунт хранится до 24 часов.","अस्थायी सुरक्षा गणक एक मिनट से एक दिन, और एक IP के अनुरोध सीमित करने हेतु अधिकतम एक घंटे रहते हैं।":"Временные счётчики защиты имеют срок от минуты до суток, в том числе до часа для ограничения запросов с одного IP-адреса.","समाप्ति पर उपयोग रुकता है; डेटाबेस अस्थायी रिकॉर्ड बाद में भौतिक रूप से हटा सकता है।":"Истечение срока исключает их использование; физическое удаление временных записей выполняется механизмом базы данных и может происходить позднее.","Plus समाप्त होने पर सत्यापित खाता और ऑर्डर इतिहास अपने-आप नहीं मिटते।":"Подтверждённый аккаунт и история заказов автоматически не удаляются при окончании Plus.","पहुँच बहाल करने के लिए जरूरत तक खाता रहता है; हटाने के नियम अगले अनुभाग में हैं।":"Аккаунт хранится для восстановления доступа, пока он нужен пользователю; удаление запрашивается по правилам следующего раздела.","भुगतान और अनुरोध डेटा अनुबंध, वापसी, विवाद और अनिवार्य लेखांकन के लिए जरूरी अवधि तक रहता है, फिर मिटता या अनाम किया जाता है।":"Данные платежей и обращений сохраняются только на срок, необходимый для исполнения обязательств, возвратов, разрешения споров и обязательного учёта, затем удаляются или обезличиваются.","अनिवार्य रिकॉर्ड खाता मिटने के बाद भी रह सकते हैं।":"Обязательные записи могут сохраняться после удаления аккаунта.","सर्वर कनेक्शन HTTPS से सुरक्षित है।":"Соединение с сервером защищено HTTPS.","अनुरोध सीमाएँ, ऑर्डर स्वामी सत्यापन, अवसंरचना पहुँच नियंत्रण और खुले कोड तथा टोकन के बजाय हैश उपयोग होते हैं।":"Применяются ограничение запросов, проверка принадлежности заказа, контроль доступа к инфраструктуре и хранение хешей вместо открытых кодов и серверных токенов.","अपना प्रवेश कोड किसी को न दें।":"Не передавай другим людям код входа.","केवल «सफलता» पेज का पता भुगतान या सक्रियण का प्रमाण नहीं; सर्वर सेवा की सूचना और विवरण जाँचता है।":"Оплата и активация не подтверждаются одним только адресом страницы «успех»: сервер проверяет уведомление и сведения платёжного сервиса.","7. डेटा सुधारना और हटाना":"7. Уточнение и удаление данных","खाता मिटाना चाहते हैं?":"Хочешь удалить аккаунт?","खाते वाले ईमेल से लिखें":"Напиши с почты аккаунта на",", विषय: «Hanzi Bloom खाता हटाएँ»। बताएँ कि सर्वर खाता मिटाना है।":", тема: «Удаление аккаунта Hanzi Bloom». Укажи, что нужно удалить серверный аккаунт.","अपने डेटा की जानकारी, सुधार, रोक या हटाने का अनुरोध और सहमति आधारित प्रसंस्करण की सहमति वापस ले सकते हैं।":"Можно запросить сведения об обработке своих данных, исправление, блокирование или удаление, а также отозвать согласие, если обработка основана на нём.","खाते की रक्षा हेतु नियंत्रक स्वामी की पहचान जाँचता है।":"Для защиты аккаунта оператор проверяет, что обращается его владелец.","अनुरोध के लिए कार्ड, CVC या प्रवेश कोड नहीं चाहिए।":"Карта, CVC и код входа для обращения не нужны.","कानून कुछ रिकॉर्ड रखना माँगे तो उत्तर में बताया जाता है।":"Если сохранить часть записей требует закон, сообщаем об этом при ответе.","अनुरोध लागू कानूनी समयसीमा में देखे जाते हैं।":"Обращения рассматриваются в применимые законные сроки.","खाता मिटने से उसमें प्रवेश और Plus बहाली समाप्त होती है; सक्रिय खरीद मिटाने से पहले सेवा छोड़ने और वापसी पर अलग चर्चा हो सकती है, इसके अनुसार:":"Удаление аккаунта прекращает возможность входа и восстановления Plus через него; перед удалением действующей покупки можно отдельно обсудить отказ от услуги и возврат по","प्रस्ताव":"оферте","स्थानीय प्रगति Android या ऐप सेटिंग से हटती है।":"Удаление локального прогресса выполняется через настройки Android или приложения.","स्वतंत्र बाहरी सेवाओं को ऊपर जुड़ी उनकी नीतियों के अनुसार अनुरोध भेज सकते हैं।":"Запросы к самостоятельным внешним сервисам можно направлять им по указанным выше политикам.","डेटा सुरक्षा के लिए नियंत्रक, अधिकृत प्राधिकरण Roskomnadzor या अदालत से संपर्क कर सकते हैं।":"По вопросам защиты персональных данных можно обратиться к оператору, а также в уполномоченный орган — Роскомнадзор — или в суд.","8. बच्चे और नीति बदलाव":"8. Дети и изменения политики","खरीद खाता कानूनी रूप से सक्षम खरीदार उपयोग करता है; आवश्यकता पर कानूनी प्रतिनिधि खरीदता है।":"Аккаунт для покупки используется дееспособным покупателем; при необходимости покупку совершает законный представитель.","प्रतिनिधि बच्चे के डेटा पर नियंत्रक से संपर्क कर सकता है।":"В обращении о данных ребёнка представитель может связаться с оператором.","खरीद के लिए जन्मतिथि नहीं माँगी जाती।":"Приложение не запрашивает дату рождения для покупки.","नया संस्करण बदलाव की तारीख सहित इसी पते पर प्रकाशित होता है।":"Новая редакция публикуется по этому адресу с датой изменения.","अलग सहमति जरूरी होने वाले उद्देश्य या डेटा वर्ग बदलें तो पाठ अपडेट करना सहमति का विकल्प नहीं।":"Если меняются цели или состав обработки, для которых необходимо отдельное согласие, обновление текста само по себе его не заменяет.","पुराने संस्करण सहायता से माँग सकते हैं।":"Предыдущие редакции доступны по запросу в поддержку.","सहायता":"Поддержка","ऐप देखें":"Explore app","सुविधा के लिए अनुवाद। मूल दस्तावेज़ की भाषा: {language}।":"Translation for convenience. Original document: {language}.","मूल दस्तावेज़ दिखाएँ":"Show original document","भाषा":"Language","अपनी भाषा चुनें":"Choose your language","भाषाएँ खोजें":"Search languages","भाषा सूची बंद करें":"Close language selection","भाषा {language} कर दी गई":"Language changed to {language}","पेज की भाषा भुगतान क्षेत्र या मुद्रा नहीं बदलती।":"The page language does not change your payment region or currency.","कोई भाषा नहीं मिली":"No languages found","उपकरण की भाषा उपयोग करें":"Use device language","शानदार छलाँग!":"PERFECT KICK","{v0} — {v1}. मिल गया!":"{v0} — {v1}. Found!","{v0} · {v1} सर्विंग":"{v0} · {v1} servings","{v0} — {v1} नग":"{v0} — {v1} pcs","नया कोड · {seconds} सेकंड":"Новый код · {seconds} с","· {v0} सर्विंग":"· {v0} servings","{remaining} बाकी · {done} पूरे":"{remaining} left · {done} done","समाप्त करें · {count} खरीदे":"Finish · {count} bought"});})();
